import{_ as a,o as i,c as e,a2 as t}from"./chunks/framework.BvlN9b-o.js";const k=JSON.parse('{"title":"部署自己的 SaaS 后端","description":"","frontmatter":{"docLocale":"zh","counterpart":"/en/tutorials/single-machine-production","contentType":"guide","prev":false,"next":false},"headers":[],"relativePath":"tutorials/single-machine-production.md","filePath":"tutorials/single-machine-production.md"}'),n={name:"tutorials/single-machine-production.md"};function d(p,s,o,l,h,r){return i(),e("div",null,[...s[0]||(s[0]=[t(`<h1 id="部署自己的-saas-后端" tabindex="-1">部署自己的 SaaS 后端 <a class="header-anchor" href="#部署自己的-saas-后端" aria-label="Permalink to &quot;部署自己的 SaaS 后端&quot;">​</a></h1><p>把业务模块、迁移和 Worker Handler 提交到同一个源码版本，再用生产组合发布。当前部署模型是一次部署服务一个 Organization；企业内部资源仍需各自授权，多个业务模块也不构成多个租户。共享部署多家企业需要重新设计数据归属，见<a href="https://github.com/CaiZongyuan/axum-saas-template/blob/e87f840d6dfcfb1436042f731d0c0d7d5cadc9b2/docs/adr/0001-single-organization-deployment.md" target="_blank" rel="noreferrer">单企业部署 ADR</a>。</p><p>本指南需要 Docker Compose、Rust/Node/pnpm 工具链、可访问的 TLS 域名，以及已通过 HTTP 检查的业务代码。以下命令都在仓库根目录运行，会创建或更新生产数据库与对象卷。</p><h2 id="配置与构建" tabindex="-1">配置与构建 <a class="header-anchor" href="#配置与构建" aria-label="Permalink to &quot;配置与构建&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">cp</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> deploy/production/env.production.example</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> .env.production</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$EDITOR .env.production</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">just</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> production-build</span></span></code></pre></div><p>填写 <a href="https://github.com/CaiZongyuan/axum-saas-template/blob/e87f840d6dfcfb1436042f731d0c0d7d5cadc9b2/deploy/production/env.production.example" target="_blank" rel="noreferrer">环境模板</a>中的 <code>DOMAIN</code>、<code>POSTGRES_PASSWORD</code>、<code>S3_ACCESS_KEY</code>、<code>S3_SECRET_KEY</code>，确认 <code>APP_ORIGIN</code> 与 <code>S3_PUBLIC_ENDPOINT</code> 都指向公开 HTTPS 入口。密码和密钥由部署方生成，环境文件不提交到 Git，也不进入镜像。完整类型、默认值与校验见<a href="./../reference/config">配置参考</a>。</p><p>启用邮件时，API 和 Worker 必须使用相同的 <code>MAIL_ENCRYPTION_KEY</code>（32 字节 hex）；未配置 SMTP 时邮件关闭。遥测端点可以留空。配置邮件或遥测后，其出口失联也不会阻塞普通业务请求。</p><p><a href="https://github.com/CaiZongyuan/axum-saas-template/blob/e87f840d6dfcfb1436042f731d0c0d7d5cadc9b2/deploy/production/Dockerfile" target="_blank" rel="noreferrer">Dockerfile</a>构建 API/Worker 并嵌入迁移；Web 产物由 Caddy 服务。自己的迁移必须在构建上下文的 <code>migrations/</code> 内，Handler 必须在 <a href="https://github.com/CaiZongyuan/axum-saas-template/blob/e87f840d6dfcfb1436042f731d0c0d7d5cadc9b2/apps/worker/src/main.rs" target="_blank" rel="noreferrer">Worker 组装点</a>注册。容器使用非 root 用户、只读根文件系统和临时目录。</p><h2 id="显式迁移-再启动进程" tabindex="-1">显式迁移，再启动进程 <a class="header-anchor" href="#显式迁移-再启动进程" aria-label="Permalink to &quot;显式迁移，再启动进程&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">just</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> production-up</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> .env.production</span></span></code></pre></div><p><code>just</code> 的环境文件是位置参数；省略时默认使用 <code>.env.production</code>。配方按以下顺序执行：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>PostgreSQL / Redis / RustFS 健康</span></span>
<span class="line"><span>  → migrate 一次性容器</span></span>
<span class="line"><span>  → storage-init 一次性容器</span></span>
<span class="line"><span>  → API / Worker / Caddy 健康</span></span></code></pre></div><p>迁移和建桶在 <code>ops</code> profile 中显式运行。API 与 Worker 启动不会修改 schema；未迁移或迁移集合/checksum 与源码不一致时，readiness 失败。迁移失败会让配方在启动应用前退出，修复原因后重跑：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">just</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> production-migrate</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> .env.production</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">just</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> production-up</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> .env.production</span></span></code></pre></div><p><a href="https://github.com/CaiZongyuan/axum-saas-template/blob/e87f840d6dfcfb1436042f731d0c0d7d5cadc9b2/compose.production.yaml" target="_blank" rel="noreferrer">生产组合</a>只发布 Caddy 的 80/443；API、Worker、数据库、Redis 与 RustFS 留在内部网络。手动调用 Compose 时，<code>--env-file</code> 负责插值，服务的 <code>env_file</code> 还需要 <code>ENV_FILE</code>：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">ENV_FILE</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">.env.production</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> compose</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -f</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> compose.production.yaml</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --env-file</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> .env.production</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ps</span></span></code></pre></div><h2 id="验证自己的公开合同" tabindex="-1">验证自己的公开合同 <a class="header-anchor" href="#验证自己的公开合同" aria-label="Permalink to &quot;验证自己的公开合同&quot;">​</a></h2><p>在 shell 中将 <code>DOMAIN</code> 设为环境文件里的域名，再检查：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --fail</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;https://</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$DOMAIN</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">/health/live&quot;</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --fail</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;https://</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$DOMAIN</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">/health/ready&quot;</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -I</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;http://</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$DOMAIN</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">/&quot;</span></span></code></pre></div><p>预期两个健康接口返回 200，明文入口重定向到 HTTPS。随后用自己的 API 完成“创建 → 读取 → 更新”，检查重启后数据和 Session 仍有效，并执行一个 Worker 任务直到终态。资源拒绝与版本冲突也应通过同一 HTTPS 入口验证；健康接口不能证明业务授权正确。</p><p>对象 URL 使用公开入口签名。<a href="https://github.com/CaiZongyuan/axum-saas-template/blob/e87f840d6dfcfb1436042f731d0c0d7d5cadc9b2/deploy/production/Caddyfile" target="_blank" rel="noreferrer">Caddyfile</a>把桶路径原样转发给 RustFS，不能在反向代理中改写签名的 Host 或路径。新增业务应通过 Files 使用这条通道。</p><h2 id="故障与进程生命周期" tabindex="-1">故障与进程生命周期 <a class="header-anchor" href="#故障与进程生命周期" aria-label="Permalink to &quot;故障与进程生命周期&quot;">​</a></h2><table tabindex="0"><thead><tr><th>故障</th><th>需要保持的合同</th></tr></thead><tbody><tr><td>PostgreSQL 不可达</td><td>readiness 和依赖数据库的业务返回受控 503，带 request_id；恢复后无需重启</td></tr><tr><td>Redis 不可达</td><td>缓存回源数据库，限流使用有界保守回退；readiness 不因此失败</td></tr><tr><td>RustFS 不可达</td><td>数据库内容仍可读；对象上传/完成返回受控失败，恢复后可重试</td></tr><tr><td>邮件或遥测出口失联</td><td>业务继续；邮件由 Job 重试，遥测导出与停止刷新有截止时间</td></tr><tr><td>Worker 停止</td><td>请求可入队，任务保存在 PostgreSQL，Worker 恢复后继续认领</td></tr></tbody></table><p>停止 API 先 drain HTTP 请求；停止 Worker 先停止认领并排空在手工作。</p><table tabindex="0"><thead><tr><th>进程</th><th>内部停止期限</th><th>Compose 宽限期</th></tr></thead><tbody><tr><td>API</td><td>HTTP 排空 3 秒、连接池关闭 1 秒，再有界刷新遥测</td><td>30 秒</td></tr><tr><td>Worker</td><td>在手任务 <code>JOB_SHUTDOWN_SECS</code>（默认 10 秒），健康 HTTP 与连接池各 1 秒，再有界刷新遥测</td><td>45 秒</td></tr></tbody></table><p>遥测 trace 刷新最多 2 秒，metrics reader 使用 SDK 的 5 秒停止等待。生产 smoke 和备份要求 API 在 25 秒前、Worker 在 40 秒前退出并具有 drain 日志，以避开强杀宽限期。调大任务收尾期限时同步检查总预算与 Compose 宽限期；自己的 Handler 也要尊重取消、租约和退出期限，不能用无限等待阻塞维护窗口。</p><h2 id="升级与失败恢复" tabindex="-1">升级与失败恢复 <a class="header-anchor" href="#升级与失败恢复" aria-label="Permalink to &quot;升级与失败恢复&quot;">​</a></h2><p>先按<a href="./backup-restore">备份指南</a>生成并核对归档，再停止旧应用、构建已审阅版本并迁移：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">just</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> production-down</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> .env.production</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">just</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> production-build</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">just</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> production-up</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> .env.production</span></span></code></pre></div><p><code>production-down</code> 保留数据卷。迁移失败时保留失败日志与数据库，排除问题后重试；新迁移可能已提交，不能假定换回旧镜像就能回滚 schema。恢复应进入独立环境，并使用归档对应的应用版本。</p><p>框架的可重复验证入口是：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">node</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --test</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tests/tooling/production-compose.test.mjs</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">just</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> production-smoke</span></span></code></pre></div><p><code>production-smoke</code> 创建测试密钥和临时生产组合，经真实 TLS 验证参考应用、依赖故障、持久性和 drain，结束删除其测试卷。它需要空闲的 80/443，不能与现有生产入口共用端口；它不验证读者新增的业务，应补自己的 HTTPS 旅程。</p><p>下一步：<a href="./backup-restore">保护业务数据并验证独立恢复</a>。</p><hr><p>源码版本：<code>e87f840d6dfc</code> · <a href="https://github.com/CaiZongyuan/axum-saas-template/blob/e87f840d6dfcfb1436042f731d0c0d7d5cadc9b2/docs/tutorials/21-single-machine-production.md" target="_blank" rel="noreferrer">本页 Markdown</a></p>`,36)])])}const u=a(n,[["render",d]]);export{k as __pageData,u as default};
